<?php require "db.php";$pageTitle="Trips";$msg="";if($_SERVER["REQUEST_METHOD"]==="POST"){$v=(int)($_POST["vehicle_id"]??0);$d=(int)($_POST["driver_id"]??0);$o=trim($_POST["origin"]??"");$dest=trim($_POST["destination"]??"");$date=$_POST["trip_date"]??"";$st=$_POST["status"]??"Scheduled";if($v&&$d&&$o&&$dest&&$date){$s=$conn->prepare("INSERT INTO trips(vehicle_id,driver_id,origin,destination,trip_date,status) VALUES(?,?,?,?,?,?)");$s->bind_param("iissss",$v,$d,$o,$dest,$date,$st);$msg=$s->execute()?"Trip created successfully.":"Could not create trip.";}else $msg="Complete all fields and select a vehicle and driver.";} $vs=$conn->query("SELECT id,vehicle_number FROM vehicles WHERE status='Available'");$ds=$conn->query("SELECT id,name FROM drivers WHERE status='Available'");$list=$conn->query("SELECT t.*,v.vehicle_number,d.name driver_name FROM trips t LEFT JOIN vehicles v ON v.id=t.vehicle_id LEFT JOIN drivers d ON d.id=t.driver_id ORDER BY t.id DESC");include "includes/header.php";?><div class="page-head"><div><p class="eyebrow">ROUTE PLANNING</p><h1>Trips</h1><p>Schedule and track vehicle journeys.</p></div></div><?php if($msg):?><p class="notice"><?=htmlspecialchars($msg)?></p><?php endif;?><section class="panel"><h2>Schedule a trip</h2><?php if(!$vs->num_rows||!$ds->num_rows):?><p class="muted">Add an available vehicle and driver first.</p><?php endif;?><form method="post" class="form-grid"><label>Vehicle<select name="vehicle_id" required><option value="">Select vehicle</option><?php while($x=$vs->fetch_assoc()):?><option value="<?=$x["id"]?>"><?=htmlspecialchars($x["vehicle_number"])?></option><?php endwhile;?></select></label><label>Driver<select name="driver_id" required><option value="">Select driver</option><?php while($x=$ds->fetch_assoc()):?><option value="<?=$x["id"]?>"><?=htmlspecialchars($x["name"])?></option><?php endwhile;?></select></label><label>Origin<input name="origin" required></label><label>Destination<input name="destination" required></label><label>Trip date<input type="date" name="trip_date" required></label><label>Status<select name="status"><option>Scheduled</option><option>In Progress</option><option>Completed</option><option>Cancelled</option></select></label><button class="button">Create trip</button></form></section><section class="panel"><h2>Trip records</h2><?php if($list&&$list->num_rows):?><div class="table-wrap"><table><tr><th>Trip</th><th>Route</th><th>Date</th><th>Vehicle</th><th>Driver</th><th>Status</th></tr><?php while($x=$list->fetch_assoc()):?><tr><td>#<?=$x["id"]?></td><td><?=htmlspecialchars($x["origin"])?> → <?=htmlspecialchars($x["destination"])?></td><td><?=$x["trip_date"]?></td><td><?=htmlspecialchars($x["vehicle_number"]??"—")?></td><td><?=htmlspecialchars($x["driver_name"]??"—")?></td><td><span class="badge"><?=htmlspecialchars($x["status"])?></span></td></tr><?php endwhile;?></table></div><?php else:?><p class="muted">No trips scheduled yet.</p><?php endif;?></section><?php include "includes/footer.php";?>